package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="spms_monitoring_feedback")public class PerformanceMonitoringFeedback extends RspAuditedEntity{@Column(name="monitoring_update_id",nullable=false,length=36)private String monitoringUpdateId;@Column(name="decision",nullable=false,length=20)private String decision;@Column(name="feedback",length=3000)private String feedback;@Column(name="actor_employee_no",nullable=false,length=100)private String actorEmployeeNo;@Column(name="acted_at",nullable=false)private Instant actedAt;protected PerformanceMonitoringFeedback(){}public PerformanceMonitoringFeedback(String a,String update,String decision,String feedback,String actor,Instant at){super(a);monitoringUpdateId=requiredText(update,"monitoringUpdateId");this.decision=requiredText(decision,"decision");this.feedback=optionalText(feedback);actorEmployeeNo=requiredText(actor,"actorEmployeeNo");actedAt=at;}public String getMonitoringUpdateId(){return monitoringUpdateId;}public String getDecision(){return decision;}public String getFeedback(){return feedback;}public String getActorEmployeeNo(){return actorEmployeeNo;}public Instant getActedAt(){return actedAt;}}
